<body>
<div class="wrap">
  <header>
    <h1>Pemantauan Sensor Gudang<small>Simulasi suhu &amp; kelembapan · 3 ruangan</small></h1>
    <div class="actions">
      <span class="badge" id="statusBadge">Berjalan</span>
      <button type="button" id="toggleBtn">Jeda</button>
    </div>
  </header>

  <section class="panel">
    <h2>Batas Aman</h2>
    <div class="fields">
      <label class="field">
        <span>Suhu min (°C)</span>
        <input type="number" id="tempMin" step="0.5" inputmode="decimal">
      </label>
      <label class="field">
        <span>Suhu maks (°C)</span>
        <input type="number" id="tempMax" step="0.5" inputmode="decimal">
      </label>
      <label class="field">
        <span>Kelembapan min (%)</span>
        <input type="number" id="humMin" step="1" inputmode="decimal">
      </label>
      <label class="field">
        <span>Kelembapan maks (%)</span>
        <input type="number" id="humMax" step="1" inputmode="decimal">
      </label>
    </div>
    <div class="hint" id="limitHint"></div>
  </section>

  <section class="cards" id="cards"></section>

  <section class="panel">
    <div class="chart-head">
      <h2>Grafik 60 Detik Terakhir</h2>
      <div class="segmented" id="segmented">
        <button type="button" data-metric="temp" class="active">Suhu</button>
        <button type="button" data-metric="hum">Kelembapan</button>
      </div>
    </div>
    <div class="canvas-wrap" id="canvasWrap">
      <canvas id="chart"></canvas>
    </div>
    <div class="legend" id="legend"></div>
  </section>

  <section class="panel">
    <h2>Log Peringatan</h2>
    <ul class="log" id="log"></ul>
  </section>
</div>

<script>
(function () {
  'use strict';

  var MAX_POINTS = 60;
  var STORAGE_KEY = 'gudang.sensor.limits.v1';

  var ROOMS = [
    { id: 'a', name: 'Ruang A', baseTemp: 21.5, baseHum: 52 },
    { id: 'b', name: 'Ruang B', baseTemp: 24.6, baseHum: 63 },
    { id: 'c', name: 'Ruang C', baseTemp: 27.6, baseHum: 68 }
  ];

  var COLORS = { a: '#38bdf8', b: '#a78bfa', c: '#fbbf24' };

  var state = {
    paused: false,
    metric: 'temp',
    limits: { tempMin: 18, tempMax: 28, humMin: 40, humMax: 70 },
    series: {},
    status: {},
    alerts: []
  };

  ROOMS.forEach(function (r) {
    state.series[r.id] = { temp: [], hum: [] };
    state.status[r.id] = { temp: 'ok', hum: 'ok' };
  });

  var cardsEl = document.getElementById('cards');
  var legendEl = document.getElementById('legend');
  var logEl = document.getElementById('log');
  var canvas = document.getElementById('chart');
  var canvasWrap = document.getElementById('canvasWrap');
  var ctx = canvas.getContext('2d');
  var toggleBtn = document.getElementById('toggleBtn');
  var statusBadge = document.getElementById('statusBadge');
  var segmented = document.getElementById('segmented');
  var limitHint = document.getElementById('limitHint');

  var inputEls = {
    tempMin: document.getElementById('tempMin'),
    tempMax: document.getElementById('tempMax'),
    humMin: document.getElementById('humMin'),
    humMax: document.getElementById('humMax')
  };

  var cards = {};

  /* ---------- utilitas ---------- */

  function pad2(n) { return n < 10 ? '0' + n : '' + n; }

  function formatTime(d) {
    return pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds());
  }

  function nextVal(cur, base, amp) {
    var drift = (base - cur) * 0.06;
    var noise = (Math.random() - 0.5) * amp;
    return cur + drift + noise;
  }

  /* ---------- penyimpanan batas aman ---------- */

  function loadSettings() {
    try {
      var raw = window.localStorage.getItem(STORAGE_KEY);
      if (!raw) return;
      var obj = JSON.parse(raw);
      if (!obj || typeof obj !== 'object') return;
      var keys = ['tempMin', 'tempMax', 'humMin', 'humMax'];
      for (var i = 0; i < keys.length; i++) {
        var v = Number(obj[keys[i]]);
        if (isFinite(v)) state.limits[keys[i]] = v;
      }
      if (state.limits.tempMin >= state.limits.tempMax ||
          state.limits.humMin >= state.limits.humMax) {
        state.limits = { tempMin: 18, tempMax: 28, humMin: 40, humMax: 70 };
      }
    } catch (e) {
      /* localStorage tidak tersedia — pakai nilai bawaan */
    }
  }

  function saveSettings() {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state.limits));
    } catch (e) {
      /* diabaikan */
    }
  }

  function syncInputs() {
    inputEls.tempMin.value = state.limits.tempMin;
    inputEls.tempMax.value = state.limits.tempMax;
    inputEls.humMin.value = state.limits.humMin;
    inputEls.humMax.value = state.limits.humMax;
  }

  /* ---------- evaluasi status ---------- */

  function evalStatus(metric, value) {
    var L = state.limits;
    if (typeof value !== 'number' || !isFinite(value)) return 'ok';
    if (metric === 'temp') {
      if (value > L.tempMax) return 'high';
      if (value < L.tempMin) return 'low';
    } else {
      if (value > L.humMax) return 'high';
      if (value < L.humMin) return 'low';
    }
    return 'ok';
  }

  function updateStatus(room, metric, value) {
    var prev = state.status[room.id][metric];
    var next = evalStatus(metric, value);
    if (next === prev) return;
    state.status[room.id][metric] = next;

    var label = metric === 'temp' ? 'Suhu' : 'Kelembapan';
    var unit = metric === 'temp' ? ' °C' : ' %';
    var lim = metric === 'temp'
      ? (next === 'high' ? state.limits.tempMax : state.limits.tempMin)
      : (next === 'high' ? state.limits.humMax : state.limits.humMin);

    var text;
    if (next === 'ok') {
      text = room.name + ' · ' + label + ' kembali normal (' + value.toFixed(1) + unit + ')';
    } else {
      text = room.name + ' · ' + label + ' ' + value.toFixed(1) + unit +
             (next === 'high' ? ' melebihi batas atas ' : ' di bawah batas bawah ') +
             lim + unit;
    }
    addAlert(next === 'ok' ? 'info' : 'alarm', text);
  }

  function checkAll() {
    ROOMS.forEach(function (r) {
      var d = state.series[r.id];
      if (!d.temp.length || !d.hum.length) return;
      updateStatus(r, 'temp', d.temp[d.temp.length - 1]);
      updateStatus(r, 'hum', d.hum[d.hum.length - 1]);
    });
  }

  /* ---------- log peringatan ---------- */

  function addAlert(level, text) {
    state.alerts.unshift({ level: level, text: text, time: new Date() });
    if (state.alerts.length > 60) state.alerts.length = 60;
    renderLog();
  }

  function renderLog() {
    logEl.innerHTML = '';
    if (!state.alerts.length) {
      var empty = document.createElement('li');
      empty.className = 'empty';
      empty.textContent = 'Belum ada peringatan. Semua sensor dalam batas aman.';
      logEl.appendChild(empty);
      return;
    }
    var shown = state.alerts.slice(0, 20);
    var frag = document.createDocumentFragment();
    shown.forEach(function (a) {
      var li = document.createElement('li');
      li.className = 'log-item' + (a.level === 'alarm' ? ' alarm' : '');
      var t = document.createElement('span');
      t.className = 'log-time';
      t.textContent = formatTime(a.time);
      var m = document.createElement('span');
      m.className = 'log-msg';
      m.textContent = a.text;
      li.appendChild(t);
      li.appendChild(m);
      frag.appendChild(li);
    });
    logEl.appendChild(frag);
  }

  /* ---------- kartu ruangan ---------- */

  function makeRow(metric, label, unit) {
    var row = document.createElement('div');
    row.className = 'row';
    row.setAttribute('data-metric', metric);

    var l = document.createElement('span');
    l.className = 'row-label';
    l.textContent = label;

    var v = document.createElement('span');
    v.className = 'row-value';
    var b = document.createElement('b');
    b.setAttribute('data-role', metric);
    b.textContent = '--';
    var i = document.createElement('i');
    i.textContent = unit;
    v.appendChild(b);
    v.appendChild(i);

    row.appendChild(l);
    row.appendChild(v);
    return row;
  }

  function buildCards() {
    var frag = document.createDocumentFragment();
    ROOMS.forEach(function (r) {
      var card = document.createElement('article');
      card.className = 'card';
      card.id = 'card-' + r.id;

      var top = document.createElement('div');
      top.className = 'card-top';
      var h3 = document.createElement('h3');
      h3.textContent = r.name;
      var pill = document.createElement('span');
      pill.className = 'pill';
      pill.setAttribute('data-role', 'pill');
      pill.textContent = 'Aman';
      top.appendChild(h3);
      top.appendChild(pill);

      var rows = document.createElement('div');
      rows.appendChild(makeRow('temp', 'Suhu', '°C'));
      rows.appendChild(makeRow('hum', 'Kelembapan', '%'));

      card.appendChild(top);
      card.appendChild(rows);
      frag.appendChild(card);
      cards[r.id] = card;
    });
    cardsEl.appendChild(frag);
  }

  function buildLegend() {
    ROOMS.forEach(function (r) {
      var s = document.createElement('span');
      var d = document.createElement('span');
      d.className = 'dot';
      d.style.background = COLORS[r.id];
      s.appendChild(d);
      s.appendChild(document.createTextNode(r.name));
      legendEl.appendChild(s);
    });
  }

  function render() {
    ROOMS.forEach(function (r) {
      var card = cards[r.id];
      if (!card) return;
      var d = state.series[r.id];
      var st = state.status[r.id];

      var tEl = card.querySelector('[data-role="temp"]');
      var hEl = card.querySelector('[data-role="hum"]');
      tEl.textContent = d.temp.length ? d.temp[d.temp.length - 1].toFixed(1) : '--';
      hEl.textContent = d.hum.length ? d.hum[d.hum.length - 1].toFixed(1) : '--';

      var tRow = card.querySelector('[data-metric="temp"]');
      var hRow = card.querySelector('[data-metric="hum"]');
      tRow.classList.toggle('bad', st.temp !== 'ok');
      hRow.classList.toggle('bad', st.hum !== 'ok');

      var count = 0;
      if (st.temp !== 'ok') count++;
      if (st.hum !== 'ok') count++;

      card.classList.toggle('alarm', count > 0);
      var pill = card.querySelector('[data-role="pill"]');
      pill.textContent = count === 0 ? 'Aman' : (count === 1 ? 'Waspada' : 'Bahaya');
      pill.className = 'pill' + (count === 0 ? '' : (count === 1 ? ' warn' : ' danger'));
    });
  }

  /* ---------- grafik canvas ---------- */

  function getRange(metric) {
    var lo = Infinity, hi = -Infinity;
    ROOMS.forEach(function (r) {
      var arr = state.series[r.id][metric];
      for (var i = 0; i < arr.length; i++) {
        if (arr[i] < lo) lo = arr[i];
        if (arr[i] > hi) hi = arr[i];
      }
    });
    if (!isFinite(lo) || !isFinite(hi)) { lo = 0; hi = 1; }

    if (metric === 'temp') {
      lo = Math.min(lo, state.limits.tempMin);
      hi = Math.max(hi, state.limits.tempMax);
    } else {
      lo = Math.min(lo, state.limits.humMin);
      hi = Math.max(hi, state.limits.humMax);
    }
    if (hi - lo < 4) {
      var mid = (hi + lo) / 2;
      lo = mid - 2;
      hi = mid + 2;
    }
    var pad = (hi - lo) * 0.12;
    return [lo - pad, hi + pad];
  }

  function fmtTick(v, span) {
    return span < 8 ? v.toFixed(1) : String(Math.round(v));
  }

  function drawChart() {
    var rect = canvas.getBoundingClientRect();
    var w = Math.max(1, Math.round(rect.width));
    var h = Math.max(1, Math.round(rect.height));
    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    var pw = Math.round(w * dpr);
    var ph = Math.round(h * dpr);

    if (canvas.width !== pw || canvas.height !== ph) {
      canvas.width = pw;
      canvas.height = ph;
    }

    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);

    var padL = 44, padR = 12, padT = 14, padB = 22;
    var plotW = Math.max(10, w - padL - padR);
    var plotH = Math.max(10, h - padT - padB);

    var range = getRange(state.metric);
    var lo = range[0];
    var hi = range[1];
    var span = (hi - lo) || 1;

    ctx.font = '10px system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif';
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'right';

    var steps = 4;
    for (var i = 0; i <= steps; i++) {
      var val = lo + span * i / steps;
      var y = padT + plotH * (1 - i / steps);
      ctx.strokeStyle = 'rgba(120,160,220,0.14)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padL, Math.round(y) + 0.5);
      ctx.lineTo(padL + plotW, Math.round(y) + 0.5);
      ctx.stroke();

      ctx.fillStyle = '#7f93b3';
      ctx.fillText(fmtTick(val, span), padL - 8, y);
    }

    /* garis batas aman */
    var limA, limB;
    if (state.metric === 'temp') {
      limA = state.limits.tempMax;
      limB = state.limits.tempMin;
    } else {
      limA = state.limits.humMax;
      limB = state.limits.humMin;
    }
    ctx.setLineDash([4, 4]);
    ctx.lineWidth = 1;
    ctx.strokeStyle = 'rgba(248,113,113,0.55)';
    [limA, limB].forEach(function (v) {
      if (v < lo || v > hi) return;
      var y = padT + plotH * (1 - (v - lo) / span);
      ctx.beginPath();
      ctx.moveTo(padL, Math.round(y) + 0.5);
      ctx.lineTo(padL + plotW, Math.round(y) + 0.5);
      ctx.stroke();
    });
    ctx.setLineDash([]);

    /* deret data */
    ctx.save();
    ctx.beginPath();
    ctx.rect(padL, padT - 8, plotW, plotH + 16);
    ctx.clip();

    ROOMS.forEach(function (r) {
      var arr = state.series[r.id][state.metric];
      var n = arr.length;
      if (!n) return;
      var off = MAX_POINTS - n;

      ctx.beginPath();
      for (var k = 0; k < n; k++) {
        var x = padL + plotW * ((off + k) / (MAX_POINTS - 1));
        var yv = padT + plotH * (1 - (arr[k] - lo) / span);
        if (k === 0) ctx.moveTo(x, yv);
        else ctx.lineTo(x, yv);
      }
      ctx.strokeStyle = COLORS[r.id];
      ctx.lineWidth = 2;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.stroke();

      var lx = padL + plotW * ((off + n - 1) / (MAX_POINTS - 1));
      var ly = padT + plotH * (1 - (arr[n - 1] - lo) / span);
      ctx.beginPath();
      ctx.arc(lx, ly, 3, 0, Math.PI * 2);
      ctx.fillStyle = COLORS[r.id];
      ctx.fill();
    });
    ctx.restore();

    /* label sumbu waktu */
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillStyle = '#7f93b3';
    ctx.fillText('−60 s', padL, padT + plotH + 6);
    ctx.fillText('−30 s', padL + plotW * 0.5, padT + plotH + 6);
    ctx.fillText('kini', padL + plotW, padT + plotH + 6);
  }

  /* ---------- simulasi data ---------- */

  function prefill() {
    for (var i = 0; i < 24; i++) {
      ROOMS.forEach(function (r) {
        var d = state.series[r.id];
        var lt = d.temp.length ? d.temp[d.temp.length - 1] : r.baseTemp + (Math.random() - 0.5) * 2;
        var lh = d.hum.length ? d.hum[d.hum.length - 1] : r.baseHum + (Math.random() - 0.5) * 4;
        d.temp.push(nextVal(lt, r.baseTemp, 0.7));
        d.hum.push(nextVal(lh, r.baseHum, 2.4));
      });
    }
  }

  function tick() {
    if (state.paused) return;

    ROOMS.forEach(function (r) {
      var d = state.series[r.id];
      var lt = d.temp.length ? d.temp[d.temp.length - 1] : r.baseTemp;
      var lh = d.hum.length ? d.hum[d.hum.length - 1] : r.baseHum;

      d.temp.push(nextVal(lt, r.baseTemp, 0.7));
      d.hum.push(nextVal(lh, r.baseHum, 2.4));

      if (d.temp.length > MAX_POINTS) d.temp.shift();
      if (d.hum.length > MAX_POINTS) d.hum.shift();
    });

    checkAll();
    render();
    drawChart();
  }

  /* ---------- batas aman: input ---------- */

  function applyLimits() {
    var vals = {
      tempMin: parseFloat(inputEls.tempMin.value),
      tempMax: parseFloat(inputEls.tempMax.value),
      humMin: parseFloat(inputEls.humMin.value),
      humMax: parseFloat(inputEls.humMax.value)
    };

    var valid = true;
    for (var k in vals) {
      if (!isFinite(vals[k])) valid = false;
    }
    if (valid && vals.tempMin >= vals.tempMax) valid = false;
    if (valid && vals.humMin >= vals.humMax) valid = false;

    Object.keys(inputEls).forEach(function (key) {
      inputEls[key].classList.toggle('invalid', !valid);
    });

    if (!valid) {
      limitHint.textContent = 'Nilai tidak valid: isi angka dan pastikan batas minimum lebih kecil dari maksimum.';
      return;
    }

    limitHint.textContent = '';
    state.limits = vals;
    saveSettings();
    checkAll();
    render();
    drawChart();
  }

  Object.keys(inputEls).forEach(function (key) {
    inputEls[key].addEventListener('change', applyLimits);
    inputEls[key].addEventListener('blur', applyLimits);
  });

  /* ---------- interaksi lain ---------- */

  toggleBtn.addEventListener('click', function () {
    state.paused = !state.paused;
    toggleBtn.textContent = state.paused ? 'Lanjutkan' : 'Jeda';
    statusBadge.textContent = state.paused ? 'Dijeda' : 'Berjalan';
    statusBadge.classList.toggle('paused', state.paused);
  });

  segmented.addEventListener('click', function (ev) {
    var btn = ev.target.closest ? ev.target.closest('button[data-metric]') : null;
    if (!btn) return;
    var m = btn.getAttribute('data-metric');
    if (m !== 'temp' && m !== 'hum') return;
    state.metric = m;
    var all = segmented.querySelectorAll('button');
    for (var i = 0; i < all.length; i++) {
      all[i].classList.toggle('active', all[i] === btn);
    }
    drawChart();
  });

  window.addEventListener('resize', drawChart);
  window.addEventListener('orientationchange', drawChart);

  if (typeof window.ResizeObserver === 'function') {
    try {
      var ro = new window.ResizeObserver(function () { drawChart(); });
      ro.observe(canvasWrap);
    } catch (e) {
      /* diabaikan */
    }
  }

  /* ---------- inisialisasi ---------- */

  loadSettings();
  syncInputs();
  buildCards();
  buildLegend();
  prefill();
  renderLog();
  checkAll();
  render();
  drawChart();
  window.setInterval(tick, 1000);
})();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Dashboard pemantauan sensor gudang dalam satu file HTML** → seluruh dokumen `<!DOCTYPE html>` dengan CSS di `<style>` dan JavaScript di `<script>` dalam satu file.
- **Data simulasi suhu dan kelembapan dari 3 ruangan** → array `ROOMS` (Ruang A/B/C) dengan `baseTemp` dan `baseHum`, serta fungsi `nextVal()` dan `prefill()`.
- **Diperbarui setiap detik** → `window.setInterval(tick, 1000)` pada bagian inisialisasi.
- **Grafik garis real-time 60 detik terakhir dengan canvas** → elemen `<canvas id="chart">` dan fungsi `drawChart()` dengan `MAX_POINTS = 60`.
- **Batas aman yang bisa diatur** → panel "Batas Aman" (`#tempMin`, `#tempMax`, `#humMin`, `#humMax`) dan fungsi `applyLimits()`.
- **Kartu berubah merah jika melewati batas** → kelas `.card.alarm` dan `.row.bad` yang diatur di `render()` lewat `evalStatus()`.
- **Log peringatan** → `addAlert()`, `renderLog()`, dan daftar `<ul class="log" id="log">`.
- **Tombol jeda/lanjut** → `#toggleBtn` dengan penanganan `state.paused` pada `tick()`.
- **Responsif sampai lebar 375 px** → `grid-template-columns: repeat(auto-fit, minmax(215px, 1fr))`, `@media (max-width: 480px)`, dan `canvas` berukuran persentase.
- **Tanpa library, font, gambar, atau file dari luar** → tidak ada `<link>`, `<script src>`, `@import`, atau `url()` eksternal; hanya `font-family` sistem.
- **Tanpa error JavaScript** → pembungkus IIFE dengan `'use strict'`, pengecekan `isFinite`/`null`, dan penjagaan elemen sebelum dipakai.
- **Akses `localStorage` dibungkus `try/catch`** → fungsi `loadSettings()` dan `saveSettings()`.

**Catatan teknis**
- Batas aman disimpan di `localStorage` dengan kunci `gudang.sensor.limits.v1`; bila data rusak atau tidak tersedia, nilai bawaan (18–28 °C, 40–70 %) dipakai otomatis.
- Nilai input yang tidak valid (kosong atau minimum ≥ maksimum) ditandai merah dan tidak diterapkan, sehingga grafik dan status tetap memakai batas terakhir yang sah.
- Grafik digambar ulang dengan penskalaan `devicePixelRatio` (dibatasi 2×) agar tajam di layar beresolusi tinggi, dan `ResizeObserver` menjaga kanvas tetap pas saat ukuran jendela berubah.
- Saat dijeda, timer tetap berjalan tetapi `tick()` langsung keluar, sehingga data, kartu, dan log membeku; penggantian metrik grafik tetap berfungsi.

Pendekatannya: bersihkan dulu seluruh pemisah yang diizinkan (titik, tanda minus, dan spasi) di posisi mana pun, lalu kumpulkan hanya karakter digit 0–9. Jika muncul karakter lain, proses langsung gagal dengan `None`. Setelah itu, validasi jumlah digit: 15 digit diformat ke pola NPWP lama, 16 digit dikembalikan apa adanya tanpa pemisah, selain itu `None`.

```python
def normalisasi_npwp(teks: str) -> str | None:
    if not isinstance(teks, str):
        return None

    digit = []
    for ch in teks:
        if ch in ".- ":
            continue
        if "0" <= ch <= "9":
            digit.append(ch)
        else:
            return None

    angka = "".join(digit)

    if len(angka) == 15:
        return f"{angka[0:2]}.{angka[2:5]}.{angka[5:8]}.{angka[8]}-{angka[9:12]}.{angka[12:15]}"

    if len(angka) == 16:
        return angka

    return None
```

Contoh pemakaian: `normalisasi_npwp("99.999.999.9-999.999")` menghasilkan `"99.999.999.9-999.999"`; `normalisasi_npwp("1234567890123456")` menghasilkan `"1234567890123456"`; `normalisasi_npwp(" 01 234 567 8 901 000 ")` menghasilkan `"01.234.567.8-901.000"`; sedangkan `normalisasi_npwp("12 345 678 901 234")` menghasilkan `None` karena hanya berisi 14 digit. Kasus khusus yang ditangani: pemisah berulang/berada di posisi mana pun, masukan 15 digit, masukan 16 digit, karakter tidak valid seperti huruf atau simbol lain, dan jumlah digit selain 15/16.

Pendekatannya: ubah setiap porsi menjadi pecahan eksak, hitung bagian proporsional tiap orang, ambil bagian bulatnya dengan pembulatan ke bawah, lalu bagikan sisa rupiah satu per satu berdasarkan pecahan desimal terbesar. Jika pecahan sama, urutan nama menentukan penerima sisa.

```python
from fractions import Fraction

def pecah_tagihan(total: int, porsi: dict[str, float]) -> dict[str, int]:
    if total < 0:
        raise ValueError("total tidak boleh negatif")
    if not porsi:
        raise ValueError("porsi tidak boleh kosong")

    porsi_fraksi = {}
    for nama, nilai in porsi.items():
        if nilai <= 0:
            raise ValueError("setiap porsi harus lebih dari 0")
        if isinstance(nilai, float):
            porsi_fraksi[nama] = Fraction(str(nilai))
        else:
            porsi_fraksi[nama] = Fraction(nilai)

    total_porsi = sum(porsi_fraksi.values(), Fraction(0, 1))
    hasil = {}
    fraksi = {}

    for nama, nilai in porsi_fraksi.items():
        bagian = Fraction(total, 1) * nilai / total_porsi
        dasar = bagian.numerator // bagian.denominator
        hasil[nama] = dasar
        fraksi[nama] = bagian - dasar

    sisa = total - sum(hasil.values())
    urutan = sorted(hasil.keys(), key=lambda nama: (-fraksi[nama], nama))

    for nama in urutan[:sisa]:
        hasil[nama] += 1

    return hasil
```

Contoh pemakaian: `pecah_tagihan(100, {"Budi": 2, "Ani": 1})` menghasilkan `{"Budi": 67, "Ani": 33}`. Kasus khusus yang ditangani: `total=0` menghasilkan semua nilai `0`; pecahan seri dibagikan menurut urutan nama; `total` negatif, `porsi` kosong, atau ada porsi `≤ 0` akan melempar `ValueError`.

Pendekatannya: validasi setiap transaksi dengan regex ketat `YYYY-MM-DD` lalu cek tanggalnya memakai `datetime.strptime`, tolak nominal negatif, kelompokkan nominal per bulan dan kategori, kemudian susun hasil akhir dengan bulan terurut naik dan kategori terurut abjad.

```python
from datetime import datetime
import re

def rekap_bulanan(transaksi: list[dict]) -> dict[str, dict[str, int]]:
    pola_tanggal = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$")
    sementara: dict[str, dict[str, int]] = {}

    for item in transaksi:
        tanggal = item["tanggal"]
        if not isinstance(tanggal, str) or pola_tanggal.fullmatch(tanggal) is None:
            raise ValueError("Tanggal harus berformat YYYY-MM-DD")

        try:
            datetime.strptime(tanggal, "%Y-%m-%d")
        except ValueError:
            raise ValueError("Tanggal tidak valid") from None

        nominal = item["nominal"]
        if nominal < 0:
            raise ValueError("Nominal tidak boleh negatif")

        bulan = tanggal[:7]
        kategori = item["kategori"]

        if bulan not in sementara:
            sementara[bulan] = {}

        sementara[bulan][kategori] = sementara[bulan].get(kategori, 0) + nominal

    hasil: dict[str, dict[str, int]] = {}
    for bulan in sorted(sementara):
        hasil[bulan] = {
            kategori: sementara[bulan][kategori]
            for kategori in sorted(sementara[bulan])
        }

    return hasil
```

Contoh pemakaian: `rekap_bulanan([{"tanggal": "2026-01-05", "kategori": "makan", "nominal": 20000}, {"tanggal": "2026-01-10", "kategori": "makan", "nominal": 15000}, {"tanggal": "2026-02-01", "kategori": "transport", "nominal": 10000}])` menghasilkan `{"2026-01": {"makan": 35000}, "2026-02": {"transport": 10000}}`. Kasus khusus yang ditangani: tanggal salah format atau tidak valid melempar `ValueError`, nominal negatif melempar `ValueError`, nominal nol tetap diterima, bulan diurutkan naik, dan kategori dalam tiap bulan diurutkan menurut abjad.

Fungsi ini seharusnya menghitung rata-rata tertimbang, tapi `rata_rata_tertimbang([80, 90], [1, 3])` menghasilkan 135, padahal seharusnya 87.5.

```python
def rata_rata_tertimbang(nilai, bobot):
    total = 0
    for i in range(1, len(nilai)):
        total += nilai[i] * bobot[i]
    return total / len(bobot)
```

Tolong cari semua kesalahannya, jelaskan, lalu berikan versi yang benar. Fungsi juga harus melempar `ValueError` jika panjang `nilai` dan `bobot` berbeda, daftarnya kosong, atau total bobotnya 0.

Pendekatannya: jumlahkan hasil kali setiap nilai dengan bobotnya, lalu bagi dengan total bobot, bukan dengan jumlah elemen. Kesalahan kode awal: perulangan mulai dari indeks 1 sehingga elemen pertama terlewat, pembagi memakai `len(bobot)` bukan jumlah bobot, dan tidak ada validasi panjang, daftar kosong, serta total bobot nol.

```python
def rata_rata_tertimbang(nilai, bobot):
    if len(nilai) != len(bobot):
        raise ValueError("Panjang nilai dan bobot harus sama")
    if len(nilai) == 0:
        raise ValueError("Daftar nilai dan bobot tidak boleh kosong")

    total_bobot = sum(bobot)
    if total_bobot == 0:
        raise ValueError("Total bobot tidak boleh nol")

    total = 0
    for n, b in zip(nilai, bobot):
        total += n * b

    return total / total_bobot
```

Contoh pemakaian: `rata_rata_tertimbang([80, 90], [1, 3])` menghasilkan `87.5`. Kasus khusus yang ditangani: panjang `nilai` dan `bobot` berbeda, daftar kosong, dan total bobot bernilai nol semuanya melempar `ValueError`.

Pendekatannya adalah memecah bilangan menjadi kelompok tiga digit dari kanan, mengonversi tiap kelompok dengan aturan khusus untuk 10, 11, 100, dan 1000, lalu menggabungkannya dengan satuan ribu, juta, miliar, dan triliun. Nilai nol, bilangan negatif, dan batas nilai absolut 10^15 ditangani secara terpisah.

```python
def terbilang(n: int) -> str:
    if abs(n) >= 10**15:
        raise ValueError("nilai absolut harus kurang dari 10^15")

    satuan = [
        "", "satu", "dua", "tiga", "empat",
        "lima", "enam", "tujuh", "delapan", "sembilan"
    ]

    def tiga_digit(x: int) -> str:
        if x == 0:
            return ""
        if x < 10:
            return satuan[x]
        if x == 10:
            return "sepuluh"
        if x == 11:
            return "sebelas"
        if x < 20:
            return satuan[x - 10] + " belas"
        if x < 100:
            hasil = satuan[x // 10] + " puluh"
            if x % 10:
                hasil += " " + satuan[x % 10]
            return hasil
        if x == 100:
            return "seratus"
        if x < 200:
            hasil = "seratus"
            if x > 100:
                hasil += " " + tiga_digit(x - 100)
            return hasil

        hasil = satuan[x // 100] + " ratus"
        if x % 100:
            hasil += " " + tiga_digit(x % 100)
        return hasil

    if n == 0:
        return "nol"

    negatif = n < 0
    n = abs(n)

    unit = ["", "ribu", "juta", "miliar", "triliun"]
    bagian = []
    i = 0

    while n > 0:
        grup = n % 1000
        if grup:
            if i == 1 and grup == 1:
                kata = "seribu"
            else:
                kata = tiga_digit(grup)
                if i > 0:
                    kata += " " + unit[i]
            bagian.append(kata)

        n //= 1000
        i += 1

    hasil = " ".join(reversed(bagian))
    if negatif:
        hasil = "minus " + hasil

    return hasil
```

Contoh pemakaian: `terbilang(2_150_000)` menghasilkan `"dua juta seratus lima puluh ribu"`; `terbilang(0)` menghasilkan `"nol"`; `terbilang(-11)` menghasilkan `"minus sebelas"`; `terbilang(101_000)` menghasilkan `"seratus satu ribu"`; `terbilang(10**15)` melempar `ValueError`. Kasus khusus yang ditangani mencakup nol, bilangan negatif, 10, 11, 100, 1000, kelompok ribuan seperti 101.000, serta batas nilai absolut 10^15.

Pendekatannya: periksa tipe, panjang, dan karakter NIK agar hanya 16 digit angka 0–9; pecah menjadi kode wilayah, tanggal lahir, dan nomor urut; tolak kode wilayah yang memiliki segmen `00` serta nomor urut `0000`; tentukan jenis kelamin dari nilai DD (lebih dari 40 berarti perempuan dan DD dikurangi 40); susun tahun dari `tahun_acuan`; lalu validasi tanggal memakai `datetime.date`.

```python
from datetime import date

def info_nik(nik: str, tahun_acuan: int) -> dict | None:
    if not isinstance(nik, str) or len(nik) != 16:
        return None
    if any(c not in "0123456789" for c in nik):
        return None

    kode_wilayah = nik[:6]
    if any(kode_wilayah[i:i + 2] == "00" for i in (0, 2, 4)):
        return None

    nomor_urut = nik[12:16]
    if nomor_urut == "0000":
        return None

    dd_raw = int(nik[6:8])
    mm = int(nik[8:10])
    yy = int(nik[10:12])

    if dd_raw > 40:
        jenis_kelamin = "P"
        dd = dd_raw - 40
    else:
        jenis_kelamin = "L"
        dd = dd_raw

    tahun = 2000 + yy if 2000 + yy <= tahun_acuan else 1900 + yy

    try:
        tanggal_lahir = date(tahun, mm, dd)
    except ValueError:
        return None

    return {
        "kode_wilayah": kode_wilayah,
        "tanggal_lahir": tanggal_lahir,
        "jenis_kelamin": jenis_kelamin,
        "nomor_urut": nomor_urut,
    }
```

Contoh pemakaian: `info_nik("3171234505900001", 2026)` mengembalikan `{'kode_wilayah': '317123', 'tanggal_lahir': datetime.date(1990, 5, 5), 'jenis_kelamin': 'P', 'nomor_urut': '0001'}`. Kasus khusus yang ditangani: panjang bukan 16, karakter selain 0–9, salah satu segmen kode wilayah `00`, nomor urut `0000`, dan tanggal tidak valid seperti 31 Februari; semuanya mengembalikan `None`.

Pendekatannya: bersihkan dulu tanda hubung dan spasi, lalu periksa apakah panjangnya 10 atau 13. Untuk ISBN-10, pastikan 9 karakter pertama berupa angka ASCII dan karakter terakhir angka atau `X/x`, kemudian hitung bobot 10 sampai 1 modulo 11. Untuk ISBN-13, pastikan semua karakter angka, awalan `978`/`979`, lalu hitung bobot bergantian 1 dan 3 modulo 10.

```python
def validasi_isbn(teks: str) -> bool:
    if not isinstance(teks, str):
        return False

    bersih = teks.replace("-", "").replace(" ", "")

    if len(bersih) == 10:
        if any(c not in "0123456789" for c in bersih[:9]):
            return False

        cek = bersih[9]
        if cek in "Xx":
            nilai_cek = 10
        elif cek in "0123456789":
            nilai_cek = int(cek)
        else:
            return False

        nilai = [int(c) for c in bersih[:9]] + [nilai_cek]
        total = sum(n * bobot for n, bobot in zip(nilai, range(10, 0, -1)))
        return total % 11 == 0

    if len(bersih) == 13:
        if any(c not in "0123456789" for c in bersih):
            return False
        if not (bersih.startswith("978") or bersih.startswith("979")):
            return False

        total = sum(
            int(c) * (1 if i % 2 == 0 else 3)
            for i, c in enumerate(bersih)
        )
        return total % 10 == 0

    return False
```

Contoh pemakaian: `validasi_isbn("0-306-40615-2")` menghasilkan `True`; `validasi_isbn("978-0-306-40615-7")` menghasilkan `True`; `validasi_isbn("0-8044-2957-X")` menghasilkan `True`. Kasus khusus yang ditangani: spasi dan tanda hubung diabaikan, `X/x` hanya diterima sebagai karakter cek ISBN-10, ISBN-13 wajib diawali `978`/`979`, serta karakter lain, panjang salah, atau format tidak sesuai menghasilkan `False`.

Pendekatannya: hitung dulu cabang anak yang berhak—anak hidup atau anak meninggal yang masih punya keturunan berhak. Bagian pasangan disamakan dengan satu cabang anak; sisanya dibagi rata per cabang. Untuk cabang anak yang meninggal, bagian cabangnya dibagi lagi secara rekursif kepada keturunannya, dengan keturunan yang meninggal tanpa ahli waris berhak diabaikan.

```python
from fractions import Fraction

def bagian_waris(pasangan_hidup: bool, anak: list) -> dict[str, Fraction]:
    def punya_keturunan_berhak(daftar: list) -> bool:
        for x in daftar:
            if isinstance(x, str):
                return True
            if isinstance(x, dict):
                if punya_keturunan_berhak(x.get("keturunan", [])):
                    return True
        return False

    def bagi_keturunan(jumlah: Fraction, daftar: list) -> dict[str, Fraction]:
        cabang = []
        for x in daftar:
            if isinstance(x, str):
                cabang.append(x)
            elif isinstance(x, dict):
                if punya_keturunan_berhak(x.get("keturunan", [])):
                    cabang.append(x)

        if not cabang:
            return {}

        bagian = jumlah / len(cabang)
        hasil = {}

        for x in cabang:
            if isinstance(x, str):
                hasil[x] = hasil.get(x, Fraction(0)) + bagian
            else:
                sub = bagi_keturunan(bagian, x.get("keturunan", []))
                for nama, nilai in sub.items():
                    hasil[nama] = hasil.get(nama, Fraction(0)) + nilai

        return hasil

    cabang_anak = []
    for x in anak:
        if isinstance(x, str):
            cabang_anak.append(x)
        elif isinstance(x, dict):
            if punya_keturunan_berhak(x.get("keturunan", [])):
                cabang_anak.append(x)

    jumlah_cabang = len(cabang_anak)

    if jumlah_cabang == 0:
        if pasangan_hidup:
            return {"pasangan": Fraction(1, 1)}
        return {}

    hasil = {}

    if pasangan_hidup:
        bagian_satu_cabang = Fraction(1, jumlah_cabang + 1)
        hasil["pasangan"] = bagian_satu_cabang
    else:
        bagian_satu_cabang = Fraction(1, jumlah_cabang)

    for x in cabang_anak:
        if isinstance(x, str):
            hasil[x] = hasil.get(x, Fraction(0)) + bagian_satu_cabang
        else:
            sub = bagi_keturunan(bagian_satu_cabang, x.get("keturunan", []))
            for nama, nilai in sub.items():
                hasil[nama] = hasil.get(nama, Fraction(0)) + nilai

    return hasil
```

Contoh pemakaian:

```python
bagian_waris(True, ["A", {"nama": "B", "keturunan": ["C", "D"]}])
# {"pasangan": Fraction(1, 3), "A": Fraction(1, 3), "C": Fraction(1, 6), "D": Fraction(1, 6)}

bagian_waris(False, [{"nama": "A", "keturunan": [{"nama": "B", "keturunan": ["C"]}, "D"]}])
# {"C": Fraction(1, 2), "D": Fraction(1, 2)}
```

Kasus khusus yang ditangani: pasangan hidup tanpa anak mendapat seluruh warisan; anak meninggal tanpa keturunan berhak tidak dihitung; penggantian tempat bertingkat sampai cicit ditangani secara rekursif; dan jumlah semua bagian selalu tepat `1`.

Pendekatannya memodelkan setiap trayek sebagai simpul graf; dua trayek dianggap terhubung jika berbagi minimal satu halte. BFS dari semua trayek yang melewati `asal` akan menghasilkan jumlah angkot minimum, karena setiap langkah BFS berarti menaiki satu angkot lagi. Jika `asal == tujuan`, jawabannya `0`; jika tidak ada trayek yang melewati asal/tujuan atau trayeknya tidak terhubung, jawabannya `-1`.

```python
from collections import deque

def transit_minimum(rute: dict[str, list[str]], asal: str, tujuan: str) -> int:
    if asal == tujuan:
        return 0

    stop_to_routes: dict[str, list[str]] = {}
    for nama_rute, daftar_halte in rute.items():
        for halte in daftar_halte:
            stop_to_routes.setdefault(halte, []).append(nama_rute)

    awal_routes = stop_to_routes.get(asal, [])
    tujuan_routes = set(stop_to_routes.get(tujuan, []))

    if not awal_routes or not tujuan_routes:
        return -1

    queue = deque()
    jarak = {}

    for nama_rute in awal_routes:
        if nama_rute not in jarak:
            jarak[nama_rute] = 1
            queue.append(nama_rute)

    while queue:
        nama_rute = queue.popleft()

        if nama_rute in tujuan_routes:
            return jarak[nama_rute]

        for halte in rute[nama_rute]:
            for rute_lain in stop_to_routes.get(halte, []):
                if rute_lain not in jarak:
                    jarak[rute_lain] = jarak[nama_rute] + 1
                    queue.append(rute_lain)

    return -1
```

Contoh pemakaian: `transit_minimum({"M01": ["Terminal", "Pasar", "Kampus"], "M02": ["Kampus", "RSUD"]}, "Terminal", "RSUD")` menghasilkan `2`; untuk `"Pasar"` ke `"Kampus"` menghasilkan `1`. Kasus khusus yang ditangani: asal sama dengan tujuan menghasilkan `0`; halte yang tidak dilewati trayek mana pun atau trayek yang tidak saling terhubung menghasilkan `-1`.

