      </label>
      <p class="hint">
        <span>Profil tersimpan otomatis di peramban ini.</span>
        <button type="button" class="btn-mini" id="btnHapusProfil">Hapus profil</button>
      </p>
    </fieldset>

    <fieldset>
      <div class="sec-title">Pemberi Kuasa</div>
      <label class="f"><span>Nama lengkap</span>
        <input type="text" id="pkNama" placeholder="Nama sesuai KTP">
      </label>
      <label class="f"><span>NIK</span>
        <input type="text" id="pkNik" inputmode="numeric" maxlength="16" placeholder="16 digit">
      </label>
      <label class="f"><span>Alamat</span>
        <textarea id="pkAlamat" rows="2" placeholder="Alamat lengkap pemberi kuasa"></textarea>
      </label>
    </fieldset>

    <fieldset>
      <div class="sec-title">Penerima Kuasa</div>
      <div id="kuasaList"></div>
      <button type="button" class="btn-add" id="addKuasa">+ Tambah penerima kuasa</button>
    </fieldset>

    <fieldset>
      <div class="sec-title">Perkara</div>
      <label class="f"><span>Pihak lawan</span>
        <input type="text" id="pihakLawan" placeholder="Nama pihak lawan">
      </label>
      <label class="f"><span>Kedudukan pemberi kuasa</span>
        <select id="kedudukan">
          <option value="Penggugat">Penggugat</option>
          <option value="Tergugat">Tergugat</option>
        </select>
      </label>
      <label class="f"><span>Pengadilan negeri</span>
        <input type="text" id="pengadilan" placeholder="Pengadilan Negeri …">
      </label>
      <label class="f"><span>Pokok perkara</span>
        <textarea id="pokokPerkara" rows="2" placeholder="Perbuatan melawan hukum / wanprestasi / …"></textarea>
      </label>
      <div class="chk">
        <input type="checkbox" id="hakSubstitusi">
        <label for="hakSubstitusi">Berikan hak substitusi kepada penerima kuasa</label>
      </div>
    </fieldset>

    <fieldset>
      <div class="sec-title">Penandatanganan</div>
      <div class="row">
        <label class="f"><span>Nomor surat</span>
          <input type="text" id="nomorSurat" placeholder="01/SK/III/2026">
        </label>
        <label class="f"><span>Kota</span>
          <input type="text" id="kota" placeholder="Jakarta">
        </label>
      </div>
      <label class="f"><span>Tanggal</span>
        <input type="date" id="tanggal">
      </label>
    </fieldset>

  </section>

  <section class="panel preview-panel">
    <div class="paper" id="paper"></div>
  </section>
</main>

<script>
(function () {
  'use strict';

  var $ = function (sel) { return document.querySelector(sel); };
  var kuasaList = $('#kuasaList');
  var paper = $('#paper');
  var formPanel = $('#formPanel');

  var LS_KEY = 'skk_kantor_v1';
  var BULAN = ['Januari','Februari','Maret','April','Mei','Juni',
               'Juli','Agustus','September','Oktober','November','Desember'];

  var KUASA_POIN = [
    'Menghadap dan menghadapi pihak lawan, menghadiri setiap persidangan, serta mewakili Pemberi Kuasa di muka Pengadilan.',
    'Mengajukan gugatan, jawaban, replik, duplik, kesimpulan, dan dokumen lain yang diperlukan.',
    'Mengajukan alat bukti surat maupun saksi, serta mengajukan permohonan lain kepada Pengadilan.',
    'Menandatangani surat, akta, dan dokumen lain yang berkaitan dengan perkara ini.',
    'Mengajukan upaya hukum banding dan kasasi, termasuk menyusun dan menandatangani memori serta kontra memori banding dan kasasi.',
    'Melakukan perdamaian (dading) dengan pihak lawan sepanjang memperoleh persetujuan tertulis dari Pemberi Kuasa.',
    'Menerima dan menyerahkan segala sesuatu yang berkaitan dengan perkara ini.'
  ];

  /* ---------------- Utilitas ---------------- */

  function esc(s) {
    return String(s === null || s === undefined ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function isi(v, fb) {
    var s = String(v === null || v === undefined ? '' : v).trim();
    return s ? esc(s) : (fb || '..............................');
  }

  function tanggalIndo(v) {
    if (!v) return '.....................';
    var d = new Date(v + 'T00:00:00');
    if (isNaN(d.getTime())) return '.....................';
    return d.getDate() + ' ' + BULAN[d.getMonth()] + ' ' + d.getFullYear();
  }

  function ident(rows) {
    return rows.map(function (r) {
      return '<div class="ident"><span class="lbl">' + r[0] + '</span>' +
             '<span class="sep">:</span>' +
             '<span class="val">' + isi(r[1]) + '</span></div>';
    }).join('');
  }

  /* ---------------- Penerima kuasa ---------------- */

  function ambilKuasa() {
    var cards = kuasaList.querySelectorAll('.kuasa-card');
    var out = [];
    for (var i = 0; i < cards.length; i++) {
      out.push({
        nama: cards[i].querySelector('[data-f="nama"]').value,
        kta: cards[i].querySelector('[data-f="kta"]').value,
        alamat: cards[i].querySelector('[data-f="alamat"]').value
      });
    }
    return out;
  }

  function buatKartu(data) {
    data = data || {};
    var card = document.createElement('div');
    card.className = 'kuasa-card';
    card.innerHTML =
      '<div class="kuasa-head"><strong>Penerima Kuasa</strong>' +
      '<button type="button" class="btn-mini" data-hapus="1">Hapus</button></div>' +
      '<label class="f"><span>Nama advokat</span>' +
      '<input type="text" data-f="nama" placeholder="Nama lengkap, S.H."></label>' +
      '<label class="f"><span>Nomor kartu tanda anggota advokat</span>' +
      '<input type="text" data-f="kta" placeholder="Nomor KTA"></label>' +
      '<label class="f"><span>Alamat kantor</span>' +
      '<textarea rows="2" data-f="alamat"></textarea></label>';

    card.querySelector('[data-f="nama"]').value = data.nama || '';
    card.querySelector('[data-f="kta"]').value = data.kta || '';
    card.querySelector('[data-f="alamat"]').value = data.alamat || '';

    card.querySelector('[data-hapus]').addEventListener('click', function () {
      var jumlah = kuasaList.querySelectorAll('.kuasa-card').length;
      if (jumlah <= 1) {
        var fields = card.querySelectorAll('input, textarea');
        for (var i = 0; i < fields.length; i++) { fields[i].value = ''; }
      } else {
        card.parentNode.removeChild(card);
      }
      render();
    });

    kuasaList.appendChild(card);
    return card;
  }

  /* ---------------- Render pratinjau ---------------- */

  function render() {
    var kantorNama = $('#kantorNama').value.trim();
    var kuasa = ambilKuasa();
    var adaKuasa = kuasa.some(function (k) {
      return (k.nama + k.kta + k.alamat).trim() !== '';
    });
    var sub = $('#hakSubstitusi').checked;
    var ked = $('#kedudukan').value;
    var kedLawan = ked === 'Penggugat' ? 'Tergugat' : 'Penggugat';

    var daftarKuasa;
    if (adaKuasa) {
      daftarKuasa = kuasa.map(function (k, i) {
        var label = kuasa.length > 1 ? (i + 1) + '. Nama' : 'Nama';
        return '<div class="kuasa-item">' +
          '<div class="ident"><span class="lbl">' + label + '</span><span class="sep">:</span>' +
            '<span class="val">' + isi(k.nama) + '</span></div>' +
          '<div class="ident"><span class="lbl">Nomor KTA</span><span class="sep">:</span>' +
            '<span class="val">' + isi(k.kta) + '</span></div>' +
          '<div class="ident"><span class="lbl">Alamat Kantor</span><span class="sep">:</span>' +
            '<span class="val">' + isi(k.alamat) + '</span></div>' +
          '</div>';
      }).join('');
    } else {
      daftarKuasa = ident([['Nama', ''], ['Nomor KTA', ''], ['Alamat Kantor', '']]);
    }

    var ttdPenerima = kuasa.map(function (k) {
      var nama = (k.nama || '').trim();
      return '<div class="ttd-block">' +
        '<div class="ttd-space"></div>' +
        '<p class="ttd-nama"><strong>' + (nama ? esc(nama) : '..............................') + '</strong></p>' +
        '<p class="ttd-jab">' + (kantorNama ? 'Advokat pada ' + esc(kantorNama) : 'Advokat') + '</p>' +
        '</div>';
    }).join('');

    var poin = KUASA_POIN.map(function (p) { return '<li>' + p + '</li>'; }).join('');

    var klausulSub = sub
      ? 'Penerima Kuasa <strong>berhak</strong> mengalihkan kuasa ini (substitusi) kepada advokat lain, ' +
        'dengan pemberitahuan tertulis terlebih dahulu kepada Pemberi Kuasa.'
      : 'Penerima Kuasa <strong>tidak berhak</strong> mengalihkan kuasa ini (substitusi) kepada pihak lain.';

    var html =
      '<h2 class="doc-title">SURAT KUASA KHUSUS</h2>' +
      '<p class="doc-nomor">Nomor: ' + isi($('#nomorSurat').value, '..................') + '</p>' +

      '<p class="par">Yang bertanda tangan di bawah ini:</p>' +
      ident([
        ['Nama', $('#pkNama').value],
        ['NIK', $('#pkNik').value],
        ['Alamat', $('#pkAlamat').value]
      ]) +
      '<p class="par">selanjutnya dalam surat kuasa ini disebut sebagai <strong>PEMBERI KUASA</strong>.</p>' +

      '<p class="par">Dengan ini memilih domisili hukum di kantor kuasanya tersebut di bawah ini, ' +
      'memberikan kuasa kepada:</p>' +
      daftarKuasa +
      '<p class="par">selanjutnya dalam surat kuasa ini disebut sebagai <strong>PENERIMA KUASA</strong>.</p>' +

      '<p class="par par-tengah"><strong>K H U S U S</strong></p>' +

      '<p class="par">untuk dan atas nama Pemberi Kuasa mewakili kepentingan hukum Pemberi Kuasa dalam ' +
      'perkara perdata dengan pokok perkara <strong>' + isi($('#pokokPerkara').value) + '</strong>, ' +
      'sebagai <strong>' + ked + '</strong> melawan <strong>' + isi($('#pihakLawan').value) + '</strong> sebagai <strong>' + kedLawan + '</strong>, di <strong>' +
      isi($('#pengadilan').value, 'Pengadilan Negeri ...............') + '</strong>, dengan hak untuk:</p>' +

      '<ol class="doc-list">' + poin + '</ol>' +

      '<p class="par">' + klausulSub + '</p>' +

      '<p class="par">Demikian surat kuasa ini dibuat dengan sebenarnya, dalam keadaan sadar dan tanpa ' +
      'paksaan dari pihak mana pun, untuk dipergunakan sebagaimana mestinya.</p>' +

      '<p class="ttd-tanggal">' + isi($('#kota').value, '...............') + ', ' +
      tanggalIndo($('#tanggal').value) + '</p>' +

      '<div class="ttd">' +
        '<div class="ttd-col">' +
          '<p class="ttd-label">Penerima Kuasa,</p>' + ttdPenerima +
        '</div>' +
        '<div class="ttd-col">' +
          '<p class="ttd-label">Pemberi Kuasa,</p>' +
          '<div class="meterai">Meterai<br>Rp10.000</div>' +
          '<p class="ttd-nama"><strong>' +
            (($('#pkNama').value || '').trim() ? esc($('#pkNama').value) : '..............................') +
          '</strong></p>' +
        '</div>' +
      '</div>';

    paper.innerHTML = html;
  }

  /* ---------------- localStorage ---------------- */

  var timerSimpan = null;

  function simpanProfil() {
    if (timerSimpan) { clearTimeout(timerSimpan); }
    timerSimpan = setTimeout(function () {
      try {
        localStorage.setItem(LS_KEY, JSON.stringify({
          nama: $('#kantorNama').value,
          alamat: $('#kantorAlamat').value,
          kontak: $('#kantorKontak').value
        }));
      } catch (e) { /* penyimpanan tidak tersedia */ }
    }, 300);
  }

  function muatProfil() {
    try {
      var raw = localStorage.getItem(LS_KEY);
      if (!raw) { return; }
      var d = JSON.parse(raw);
      if (!d || typeof d !== 'object') { return; }
      $('#kantorNama').value = d.nama || '';
      $('#kantorAlamat').value = d.alamat || '';
      $('#kantorKontak').value = d.kontak || '';
    } catch (e) { /* data rusak atau akses ditolak */ }
  }

  /* ---------------- Inisialisasi ---------------- */

  function tanggalHariIni() {
    var t = new Date();
    var m = String(t.getMonth() + 1).padStart(2, '0');
    var d = String(t.getDate()).padStart(2, '0');
    return t.getFullYear() + '-' + m + '-' + d;
  }

  muatProfil();

  $('#tanggal').value = tanggalHariIni();
  buatKartu({ alamat: $('#kantorAlamat').value });
  render();

  formPanel.addEventListener('input', function () {
    simpanProfil();
    render();
  });

  formPanel.addEventListener('change', function () {
    render();
  });

  $('#addKuasa').addEventListener('click', function () {
    buatKartu({ alamat: $('#kantorAlamat').value });
    render();
  });

  $('#btnHapusProfil').addEventListener('click', function () {
    try { localStorage.removeItem(LS_KEY); } catch (e) { /* abaikan */ }
    $('#kantorNama').value = '';
    $('#kantorAlamat').value = '';
    $('#kantorKontak').value = '';
    render();
  });

  $('#btnCetak').addEventListener('click', function () {
    window.print();
  });

})();
</script>
</body>
</html>
```

**Cek kebutuhan**
- **Form data pemberi kuasa (nama, NIK, alamat)** → fieldset "Pemberi Kuasa" dengan `#pkNama`, `#pkNik`, `#pkAlamat`.
- **Satu atau beberapa penerima kuasa (nama advokat, nomor KTA, alamat kantor)** → wadah `#kuasaList`, fungsi `buatKartu()` dan tombol `#addKuasa`, dibaca lewat `ambilKuasa()`.
- **Pihak lawan, pengadilan negeri, pokok perkara** → `#pihakLawan`, `#pengadilan`, `#pokokPerkara` pada fieldset "Perkara".
- **Pilihan hak substitusi** → checkbox `#hakSubstitusi` dan variabel `klausulSub` di `render()`.
- **Pratinjau berubah langsung saat form diisi** → listener `input`/`change` pada `#formPanel` yang memanggil `render()`.
- **Tanggal format Indonesia** → fungsi `tanggalIndo()` dengan array `BULAN` dan `new Date(v + 'T00:00:00')`.
- **Tempat tanda tangan dan meterai** → blok `.ttd` dua kolom, `.ttd-space`, dan kotak `.meterai` bertuliskan "Meterai Rp10.000".
- **Tampilan cetak rapi di A4** → `@page{size:A4;margin:18mm}` dan aturan `@media print` yang menyembunyikan `.topbar` dan `.form-panel`.
- **Profil kantor tersimpan di localStorage** → `simpanProfil()` dan `muatProfil()` dengan kunci `skk_kantor_v1`.
- **Akses localStorage dibungkus try/catch** → seluruh `setItem`, `getItem`, dan `removeItem` berada di dalam blok `try { … } catch (e) { }`.
- **Responsif sampai 375 px** → `@media (max-width:900px)` dan `@media (max-width:480px)` yang mengubah grid jadi satu kolom, mengecilkan padding kertas, dan menyetel ulang kolom identitas.
- **Tanpa library, font, gambar, atau file eksternal** → seluruh CSS dan JavaScript inline, hanya memakai font sistem (`-apple-system`, `"Times New Roman"`, dan sejenisnya).

**Catatan teknis**
Semua teks yang diketik pengguna dilewatkan melalui `esc()` sebelum masuk ke `innerHTML`, sehingga karakter seperti `<`, `>`, dan `&` tidak merusak struktur pratinjau; nilai alamat tetap mempertahankan baris baru lewat `white-space: pre-line`. Kolom "alamat kantor" pada kartu penerima kuasa otomatis terisi dari profil kantor saat kartu dibuat, dan profil disimpan dengan penundaan 300 ms agar tidak menulis ke localStorage pada setiap ketukan tombol. Saat mencetak, hanya elemen `.paper` yang tampil; jika isi surat melebihi satu halaman, daftar kuasa dan blok tanda tangan diberi `page-break-inside: avoid` agar tidak terpotong di tengah. Sesuai SEMA Nomor 6 Tahun 1994, surat menyebut kedudukan kedua pihak (Penggugat dan Tergugat), pengadilan, dan pokok perkara; peninjauan kembali sengaja tidak dicantumkan karena tetap memerlukan surat kuasa khusus tersendiri.

Berikut simulasi tata surya dalam satu file HTML yang siap dibuka langsung di peramban.

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Simulasi Tata Surya</title>
<style>
*,*::before,*::after{box-sizing:border-box}
html,body{height:100%;margin:0}
body{
  background:#04060d;color:#e6eefc;
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
  overflow:hidden;-webkit-text-size-adjust:100%;-webkit-tap-highlight-color:transparent;
}
#stage{position:fixed;inset:0;overflow:hidden}
