    setExpanded(true);
    return true;
  }

  function tutup() {
    listbox.hidden = true;
    terbuka = false;
    setExpanded(false);
    setAktif(-1);
  }

  function teksJumlah() {
    return hasil.length
      ? hasil.length + ' kota ditemukan. Gunakan panah atas dan bawah untuk menelusuri.'
