  /* ---------- Chip & pesan batas ---------- */
  function renderChip() {
    var frag = document.createDocumentFragment();
    terpilih.forEach(function (nama) {
      var li = document.createElement('li');
      li.className = 'chip';
      var span = document.createElement('span');
      span.className = 'chip-label';
      span.textContent = nama;
